{
  "findings": [
    {
      "check_id": "CKV_GCP_62",
      "title": "Bigtable instance should have encryption explicitly enabled",
      "resource": "google_bigtable_instance.pass",
      "severity": "HIGH",
      "explanation": "The Bigtable instance specifies a KMS key for encryption, but the `encryption_config` block is missing in the cluster configuration. Without this block, the encryption settings may not be properly applied."
    }
  ],
  "patched_code": "resource "google_bigtable_instance" "pass" {
  name = "tf-instance"
  deletion_protection = true
  cluster {
    cluster_id   = "tf-instance-cluster"
    num_nodes    = 1
    storage_type = "HDD"
    kms_key_name = google_kms_crypto_key.example.name

    encryption_config {
      kms_key_name = google_kms_crypto_key.example.name
    }
  }

  labels = {
    my-label = "prod-label"
  }
}
",
  "fix_summary": "Added the `encryption_config` block to the Bigtable cluster to ensure the specified KMS key is explicitly used for encryption."
}
